 // Per-index opt-in: the plugin marks a handle when its index was declared lib=cuvs.
+// Experiment gate: buffer lib=cuvs rows on the GPU side only and defer the CPU
+// HNSW graph (see patch_cagra.py). Off unless OB_CUVS_DEFER_VSAG=1, so the
+// stock behaviour stays one env var away.
+static inline bool ob_cuvs_defer_vsag() {
+#ifdef OB_BUILD_CUVS
+  static const bool on = []() {
+    const char *env = ::getenv("OB_CUVS_DEFER_VSAG");
+    return env != nullptr && env[0] == '1';
+  }();
+  return on;
+#else
+  return false;
+#endif
+}
+// True when this index should keep deferring the CPU graph. Once the graph has
+// been materialised we stop deferring so later inserts keep it consistent.
+// Defined here (not with the fallback code) because it only touches the
+// registry, while the caller add_index() is far above the search entry points.
+static bool ob_cuvs_take_defer(void *key)
+{
+  std::lock_guard<std::mutex> guard(g_ob_cuvs_mu);
+  auto it = g_ob_cuvs_reg.find(key);
+  if (it == g_ob_cuvs_reg.end() || it->second == nullptr) { return false; }
+  if (it->second->vsag_materialized_) { return false; }
+  it->second->vsag_deferred_ = true;
+  return true;
+}
